#include "exotic/autonomy/agents/in_memory_repository.hpp"
#include "exotic/autonomy/agents/router.hpp"
#include <cassert>
using namespace exotic::autonomy;using namespace exotic::autonomy::agents;
int main(){InMemoryAgentRepository repo;AgentRegistry registry{repo};for(auto key:{"research","build","supervise"}){CapabilityDefinition d;d.key=key;d.name=key;registry.define_capability(d);}auto create=[&](std::string key,std::string cap){AgentIdentity a;a.identity_key=key;a.display_name=key;a.health=HealthState::Healthy;a.trust=TrustLevel::Elevated;a.workload.maximum_tasks=2;a.domain_scopes={"general"};auto id=registry.register_agent(a);registry.activate(id);registry.grant_capability({id,cap,0.9,0.9,0,0,Clock::now()});return id;};auto researcher=create("researcher","research");auto builder=create("builder","build");auto supervisor=create("supervisor","supervise");(void)researcher;(void)builder;AllowAllGovernanceCompatibility gov;AllowAllResourceCompatibility res;CandidateScorer scorer{repo,registry,gov,res};WorkAllocator allocator{repo,scorer};TaskRequirement req;req.job_id=2;req.proposal_id=2;req.domain="general";req.capabilities={{"research",0.8,0.8,true,1.0},{"build",0.8,0.8,true,1.0},{"supervise",0.8,0.8,true,0.5}};req.minimum_team_size=3;req.preferred_team_size=3;req.maximum_team_size=3;req.mode=WorkPlanMode::SupervisorWorkers;req.supervisor_required=true;req.supervisor_capability="supervise";auto d=allocator.allocate(req);assert(d.allocated&&d.assignment);assert(d.assignment->plan.agent_ids.size()==3);assert(d.assignment->plan.supervisor_id==supervisor);assert(d.assignment->plan.mode==WorkPlanMode::SupervisorWorkers);return 0;}
